 for(auto color:{r.colorA,r.colorB})if(color.x<0||color.x>1||color.y<0||color.y>1||color.z<0||color.z>1)return fail("颜色超出范围");
 if(!r.motion&&!r.decoration)return fail("请选择运动或装饰");if(def->requiresBackground&&r.backgroundIds.empty())return fail("此模板需要背景实例");if(def->requiresSecond&&r.secondId.empty())return fail("此模板需要两个实例");
 std::set<std::string>allIds;for(const auto&l:m.layers)if(l.instanceId.empty()||!allIds.insert(l.instanceId).second)return fail("舞台存在无效或重复实例身份");for(const auto&g:m.geometries)if(g.instanceId.empty()||!allIds.insert(g.instanceId).second)return fail("舞台存在无效或重复实例身份");std::set<std::string>roles;auto validate=[&](const std::string&id,bool unique){int i=layerIndex(m,id);return !id.empty()&&i>=0&&(!unique||roles.insert(id).second);};if(!validate(r.subjectId,true))return fail("主体实例绑定失效");
