 if(!r.anchorId.empty()&&!validate(r.anchorId,false))return fail("空间锚点实例失效");for(const auto&id:r.maskTargets){if(!validate(id,false))return fail("遮罩接收实例失效");if(m.layers[size_t(layerIndex(m,id))].locked)return fail("遮罩接收实例已锁定");}if(r.mode!=Mode::Decoration&&r.maskTargets.empty())return fail("请选择遮罩接收实例");
