  if(r.templateId=="shutter"){c={{"opacity",-1,0,true}};if(!addMotion(r.secondId,{{"opacity",-1,.5,true}}))return fail(error);}
  if(!addMotion(r.subjectId,c))return fail(error);size_t n=0;for(const auto&id:r.backgroundIds){bool orb=out.layers[size_t(layerIndex(out,id))].orbit.enabled;if(!addMotion(id,{{orb?"yaw":"x",r.strength*(orb?-2:-22),double(n++)*.13,false}}))return fail(error);}n=0;for(const auto&id:r.foregroundIds){bool orb=out.layers[size_t(layerIndex(out,id))].orbit.enabled;if(!addMotion(id,{{orb?"yaw":"x",r.strength*(orb?6:65),double(n++)*.17,false}}))return fail(error);}
