std::vector<EvaluatedGeometry> evaluateGeometry(const StageModel&m,TimeUs t,const std::vector<Plane>&world,bool motion){std::vector<EvaluatedGeometry>v;v.reserve(m.geometries.size());for(const auto&g:m.geometries){EvaluatedGeometry e;e.geometry=g;e.plane=g.plane;e.opacity=g.opacity;e.active=g.enabled&&g.visible;
 if(motion&&g.reveal>0&&g.revealPeriod>0){
  const TimeUs elapsed=std::max(TimeUs(0),t-g.revealStart);
  const double u=g.revealLoop?double(elapsed%g.revealPeriod)/double(g.revealPeriod):std::clamp(double(elapsed)/double(g.revealPeriod),0.0,1.0);
  auto smooth=[](double x){x=std::clamp(x,0.0,1.0);return x*x*(3-2*x);};
  e.geometry.progress=std::min(smooth(u/.22),smooth((1-u)/.22));
 }if(!g.ownerId.empty()){auto owner=std::find_if(m.presetInstances.begin(),m.presetInstances.end(),[&](const PresetInstance&p){return p.instanceId==g.ownerId;});if(owner!=m.presetInstances.end()&&(t<owner->start||t>owner->end))e.active=false;}auto value=[&](const char*p,double base){auto it=g.animation.find(p);double b=motion&&it!=g.animation.end()?it->second.value(t,base):base;return motion?combine(b,p,motionOffset(m,g.instanceId,p,t)):b;};e.plane.position={value("x",g.plane.position.x),value("y",g.plane.position.y),value("z",g.plane.position.z)};e.plane.rotation={value("rx",g.plane.rotation.x),value("ry",g.plane.rotation.y),value("rz",g.plane.rotation.z)};e.plane.scaleX=value("sx",g.plane.scaleX);e.plane.scaleY=value("sy",g.plane.scaleY);e.opacity=std::clamp(value("opacity",g.opacity),0.0,1.0);
 if(g.referenceWidth>0&&g.referenceHeight>0&&g.anchorId.empty()&&!g.localMask){const double x=double(m.width)/g.referenceWidth,y=double(m.height)/g.referenceHeight,uniform=std::min(x,y);e.geometry.width*=x;e.geometry.height*=y;e.geometry.spacing*=uniform;e.geometry.thickness*=uniform;e.geometry.softness*=uniform;e.plane.position.x=g.layoutPivot.x+(e.plane.position.x-g.layoutPivot.x)*x;e.plane.position.y=g.layoutPivot.y+(e.plane.position.y-g.layoutPivot.y)*y;}

 if(!g.anchorId.empty()){int i=layerIndex(m,g.anchorId);if(i<0||size_t(i)>=world.size())e.active=false;else if(!g.localMask&&!g.screenFixed){const auto&p=world[size_t(i)];e.plane.position=bindPosition(e.plane.position,p);e.plane.rotation=composeRotation(p.rotation,e.plane.rotation);e.plane.scaleX*=p.scaleX;e.plane.scaleY*=p.scaleY;}}
 if(g.mode!=Mode::Decoration){bool receiver=false;for(const auto&id:g.receivers)receiver=receiver||layerIndex(m,id)>=0;if(!receiver)e.active=false;}
 if(!finite(e.plane)||!std::isfinite(e.opacity))e.active=false;v.push_back(std::move(e));}return v;}
bool removePreset(StageModel&m,const std::string&id,std::string&error){
 error.clear();auto it=std::find_if(m.presetInstances.begin(),m.presetInstances.end(),[&](const PresetInstance&p){return p.instanceId==id;});if(it==m.presetInstances.end()){error="找不到预设实例";return false;}
 for(const auto&g:m.geometries)if(g.ownerId==id&&g.locked){error="预设图形已锁定";return false;}
 for(const auto&track:it->generatedTracks){int o=targetObject(m,track.targetId);if(o==INT_MIN)continue;const auto&a=objectAnimation(m,o);auto curve=a.find(track.parameter);if(objectLocked(m,o)||(curve!=a.end()&&curve->second.locked)){error="预设参数轨已锁定";return false;}if(curve==a.end()||!sameCurve(curve->second,track.after)){error="预设关键帧已被编辑，请撤销编辑或手动移除该参数轨";return false;}}
 for(const auto&track:it->generatedTracks){int o=targetObject(m,track.targetId);if(o==INT_MIN)continue;auto&a=objectAnimation(m,o);if(track.existed)a[track.parameter]=track.before;else a.erase(track.parameter);}
 m.geometries.erase(std::remove_if(m.geometries.begin(),m.geometries.end(),[&](const Geometry&g){return g.ownerId==id;}),m.geometries.end());m.motionBlocks.erase(std::remove_if(m.motionBlocks.begin(),m.motionBlocks.end(),[&](const MotionBlock&b){return b.ownerId==id;}),m.motionBlocks.end());m.presetInstances.erase(it);return true;
}
bool bakePreset(StageModel&m,const std::string&id,TimeUs start,TimeUs end,TimeUs step,std::string&error){error.clear();auto fail=[&](const char*s){error=s;return false;};if(start<0||end<=start||step<=0||((end-start)/step+((end-start)%step!=0))>10000)return fail("烘焙区间无效或超过 10001 个采样点");if(std::none_of(m.presetInstances.begin(),m.presetInstances.end(),[&](const PresetInstance&p){return p.instanceId==id;}))return fail("找不到预设实例");StageModel out=m;bool any=false;
 for(const auto&b:m.motionBlocks)if(b.ownerId==id&&overlaps(start,end,b.start,b.end)){any=true;int o=targetObject(out,b.targetId);if(o==INT_MIN)return fail("烘焙绑定失效");if(objectLocked(out,o))return fail("烘焙对象已锁定");for(const auto&ch:b.channels){auto&c=objectAnimation(out,o)[ch.parameter];if(c.locked)return fail("烘焙参数轨已锁定");double base=baseValue(out,o,ch.parameter);std::vector<AnimKey>keys;TimeUs a=std::max(start,b.start),z=std::min(end,b.end);for(TimeUs t=a;;){keys.push_back({t,combine(c.value(t,base),ch.parameter,blockOffset(b,ch,t)),Interpolation::Linear});if(t==z)break;t=z-t<step?z:t+step;}GeneratedTrack track;track.targetId=b.targetId;track.parameter=ch.parameter;auto original=objectAnimation(m,o).find(ch.parameter);track.existed=original!=objectAnimation(m,o).end();track.before=c;
 auto&tracks=std::find_if(out.presetInstances.begin(),out.presetInstances.end(),[&](const PresetInstance&p){return p.instanceId==id;})->generatedTracks;auto prior=std::find_if(tracks.begin(),tracks.end(),[&](const GeneratedTrack&t){return t.targetId==track.targetId&&t.parameter==track.parameter;});if(prior!=tracks.end()&&!sameCurve(c,prior->after))return fail("已烘焙参数轨被编辑，请先撤销编辑");
 bakeInterval(c,a,z,base,keys);track.after=c;if(o>=-1){if(prior==tracks.end())tracks.push_back(std::move(track));else prior->after=c;}}}
 if(!any)return fail("所选区间没有循环块");std::vector<MotionBlock>blocks;for(auto b:out.motionBlocks){if(b.ownerId!=id||!overlaps(start,end,b.start,b.end)){blocks.push_back(std::move(b));continue;}auto original=b;if(original.start<start){b.end=start-1;blocks.push_back(b);}if(original.end>end){b=original;b.instanceId=fresh();b.start=end+1;b.timeOrigin=original.timeOrigin<0?original.start:original.timeOrigin;blocks.push_back(b);}}out.motionBlocks=std::move(blocks);m=std::move(out);return true;}
