 auto*ps=obs_data_get_array(d,"presets_instances");for(size_t i=0;i<std::min(size_t(256),obs_data_array_count(ps));++i){auto*v=obs_data_array_item(ps,i);PresetInstance p;p.instanceId=obs_data_get_string(v,"instance_id");p.definitionId=obs_data_get_string(v,"definition_id");p.label=obs_data_get_string(v,"label");p.version=int(num(v,"version",1,1,100000));p.seed=uint32_t(obs_data_get_int(v,"seed"));p.start=timeIn(v,"start_us");p.end=timeIn(v,"end_us");auto*s=obs_data_get_obj(v,"definition_snapshot");if(s)p.definitionSnapshot=obs_data_get_json(s);obs_data_release(s);auto*ts=obs_data_get_array(v,"generated_tracks");for(size_t j=0;j<std::min(size_t(1024),obs_data_array_count(ts));++j){auto*r=obs_data_array_item(ts,j);GeneratedTrack track;track.targetId=refIn(r,"target");track.parameter=obs_data_get_string(r,"parameter");track.existed=flag(r,"existed",false);auto*before=obs_data_get_obj(r,"before");auto ba=animationIn(before);obs_data_release(before);auto*after=obs_data_get_obj(r,"after");auto aa=animationIn(after);obs_data_release(after);if(parameter(track.parameter)&&aa.count(track.parameter)){track.before=ba[track.parameter];track.after=aa[track.parameter];p.generatedTracks.push_back(std::move(track));}obs_data_release(r);}obs_data_array_release(ts);if(unique(p.instanceId)&&p.end>=p.start)m.presetInstances.push_back(std::move(p));obs_data_release(v);}obs_data_array_release(ps);
